  "helpSupportSub": "ನಿಮ್ಮ ಧ್ವನಿಯು ಭವಿಷ್ಯವನ್ನು ರೂಪಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ",
  "founderVision": "ಸಂಸ್ಥಾಪಕರ ದೃಷ್ಟಿಕೋನ",
  "founderMessageTitle": "ನಮ್ಮ ಸಂಸ್ಥಾಪಕರಿಂದ ಸಂದೇಶ",
  "founderPara1": "{appName} ಗೆ ಸುಸ್ವಾಗತ. ಸಿರ್ಕಾಡಿಯನ್ ಜೀವಶಾಸ್ತ್ರ, ಸ್ಮಾರ್ಟ್ ಪೋಷಕಾಂಶಗಳು ಮತ್ತು ನಿರಂತರ ಗ್ಲೂಕೋಸ್ ಮೇಲ್ವಿಚಾರಣೆಯ ಮೂಲಕ ದೀರ್ಘಕಾಲದ ಜೀವನಶೈಲಿ ಸಮಸ್ಯೆಗಳನ್ನು ನೈಸರ್ಗಿಕವಾಗಿ ಗುಣಪಡಿಸುವ ಆಳವಾದ ಆಸಕ್ತಿಯಿಂದ ನಮ್ಮ ವೇದಿಕೆ ಪ್ರಾರಂಭವಾಯಿತು.",
  "founderPara2": "ಪುರಾವೆ ಆಧಾರಿತ ಜೀವನಶೈಲಿ ಪ್ರೋಟೋಕಾಲ್‌ಗಳು, ವೈಯಕ್ತಿಕಗೊಳಿಸಿದ ಆಹಾರ ಸ್ಪೈಕ್ ಸ್ಕೋರ್‌ಗಳು ಮತ್ತು ನೈಜ-ಸಮಯದ ವೈದ್ಯಕೀಯ ಮಾರ್ಗದರ್ಶನ ನಿಮ್ಮ ಬೆರಳ ತುದಿಯಲ್ಲಿರುವಂತೆ ನಾವು ಈ ವೇದಿಕೆಯನ್ನು ನಿರ್ಮಿಸಿದ್ದೇವೆ. ನಿಮ್ಮ ಆರೋಗ್ಯ ಪ್ರಯಾಣವು ವೈಯಕ್ತಿಕವಾಗಿದೆ ಮತ್ತು ನೀವು ರೋಗಮುಕ್ತ, ಶಕ್ತಿಯುತ ಜೀವನ ನಡೆಸಲು ಸಹಾಯ ಮಾಡುವುದೇ ನಮ್ಮ ಗುರಿ.",
  "founderPara3": "ನಮ್ಮ ವೇದಿಕೆಯ ಮೇಲೆ ನಂಬಿಕೆ ಇಟ್ಟು ಈ ತಡೆಗಟ್ಟುವ ಆರೋಗ್ಯ ಆಂದೋಲನದಲ್ಲಿ ಭಾಗಿಯಾಗಿದ್ದಕ್ಕಾಗಿ ಧನ್ಯವಾದಗಳು.",
  "theFoundersTeam": "ಸಂಸ್ಥಾಪಕರ ತಂಡ",
  "developerNote": "ಡೆವಲಪರ್ ಟಿಪ್ಪಣಿ",
  "behindEngineeringTitle": "ಎಂಜಿನಿಯರಿಂಗ್ & AI ವೇದಿಕೆಯ ಹಿಂದೆ",
  "developerPara1": "{appName} ಅನ್ನು ನಿರ್ಮಿಸುವುದು ಎಂಜಿನಿಯರಿಂಗ್ ಆಸಕ್ತಿ, ತಾಂತ್ರಿಕ ನಿಖರತೆ ಮತ್ತು ಕಾಳಜಿಯ ಅಸಾಧಾರಣ ಪ್ರಯಾಣವಾಗಿದೆ. ನಿರಂತರ ಗ್ಲೂಕೋಸ್ ಸಂವೇದಕ ಏಕೀಕರಣ ಮತ್ತು ಸ್ವಯಂಚಾಲಿತ ಆಹಾರ ಸ್ಪೈಕ್ ಅಲ್ಗಾರಿದಮ್‌ಗಳಿಂದ ಹಿಡಿದು ತಡೆರಹಿತ ಕ್ಲಿನಿಕಲ್ ಸಮಾಲೋಚನೆಗಳವರೆಗೆ ಎಲ್ಲವನ್ನೂ ಅರ್ಥಗರ್ಭಿತವಾಗಿ ಮತ್ತು ವೇಗವಾಗಿ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ.",
  "developerPara2": "ನಮ್ಮ ಕೋಡ್ ವ್ಯಕ್ತಿಗಳಿಗೆ ಅವರ ಆರೋಗ್ಯವನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲು, ಗ್ಲೂಕೋಸ್ ಏರಿಕೆಯನ್ನು ತಪ್ಪಿಸಲು ಮತ್ತು ಆರೋಗ್ಯಕರ ದೈನಂದಿನ ಅಭ್ಯಾಸಗಳನ್ನು ನಿರ್ಮಿಸಲು ನೇರವಾಗಿ ಸಹಾಯ ಮಾಡುತ್ತದೆ ಎಂದು ತಿಳಿಯುವುದು ನಮ್ಮ ಕೆಲಸಕ್ಕೆ ಅಪಾರ ಉದ್ದೇಶವನ್ನು ನೀಡುತ್ತದೆ.",
  "developerPara3": "ನೀವು ಎಂದಾದರೂ ಸಲಹೆಗಳನ್ನು ಹೊಂದಿದ್ದರೆ, ದೋಷವನ್ನು ಕಂಡುಕೊಂಡರೆ ಅಥವಾ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಬಯಸಿದರೆ, ದಯವಿಟ್ಟು ರೇಟಿಂಗ್ & ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ನೀಡಿ. ನಾವು ಪ್ರತಿಯೊಂದು ಟಿಪ್ಪಣಿಯನ್ನು ಓದುತ್ತೇವೆ!",
