  "habits.fastingEatingWindowGuidelines": "ತಿನ್ನುವ ಸಮಯದ ಮಾರ್ಗಸೂಚಿಗಳು: ರಾತ್ರಿ 7 ರೊಳಗೆ ಊಟ ಮುಗಿಸಿ, ಬೆಳಿಗ್ಗೆ 9 ರೊಳಗೆ ಉಪಾಹಾರ ಸೇವಿಸಿ. ಕ್ಯಾಲೊರಿ ಕಾಪಾಡಿಕೊಳ್ಳಿ ಮತ್ತು ಸಂಸ್ಕರಿಸಿದ ಆಹಾರವನ್ನು ತಪ್ಪಿಸಿ.",
