  "mia.continueCardDesc": "ಮುಂದಿನ 2 ಪೂರ್ಣ ವಾರಗಳವರೆಗೆ ನಿಮ್ಮ 4 ಜೀವನಶೈಲಿ ಬದಲಾವಣೆಗಳನ್ನು ಮುಂದುವರಿಸಿ. ಸಣ್ಣ ಸ್ಥಿರ ಹೆಜ್ಜೆಗಳು ಸೆಲ್ಯುಲಾರ್ ಮಟ್ಟದಲ್ಲಿ ಶಾಶ್ವತ ಬದಲಾವಣೆಯನ್ನು ತರುತ್ತವೆ. ಸಹಾಯ ಬೇಕಾದಾಗ ಯಾವಾಗ ಬೇಕಾದರೂ ಬನ್ನಿ. ಅದ್ಭುತವಾಗಿ ಮಾಡುತ್ತಿದ್ದೀರಿ! 💚",
