  "disclaimer.understandAndAccept": "ನಾನು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಒಪ್ಪುತ್ತೇನೆ",
  "disclaimer.cancerTreatmentText": "ಜೀವನಶೈಲಿ ಮಾರ್ಗದರ್ಶನ ಮತ್ತು ಕಾನೂನು ಹಕ್ಕುತ್ಯಾಗ\nಈ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿರುವ ಶಿಫಾರಸುಗಳು ಶೈಕ್ಷಣಿಕ ಮತ್ತು ಸಾಮಾನ್ಯ ಕ್ಷೇಮ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮಾತ್ರ. ಅವು ವೈದ್ಯಕೀಯ ಚಿಕಿತ್ಸೆಗೆ ಪರ್ಯಾಯವಲ್ಲ.\n\nಶಿಫಾರಸು ಮಾಡಿದ ಆರೋಗ್ಯಕರ ಅಭ್ಯಾಸಗಳು:\n• ಸಂಜೆ 7:00 ಗಂಟೆಯೊಳಗೆ ಊಟವನ್ನು ಮುಗಿಸಿ.\n• ಪ್ರತಿದಿನ ಕನಿಷ್ಠ 20 ನಿಮಿಷಗಳ ಕಾಲ ವ್ಯಾಯಾಮ ಮಾಡಿ.\n• ಒತ್ತಡ ಕಡಿಮೆ ಮಾಡುವ ಚಟುವಟಿಕೆಗಳಲ್ಲಿ ತೊಡಗಿಸಿಕೊಳ್ಳಿ.\n• ಪ್ರಶಾಂತ ನಿದ್ರೆಗೆ ಆದ್ಯತೆ ನೀಡಿ.",
