  "insight.walkingAfterMeals": "ಪ್ರಮುಖ ಊಟದ ನಂತರ 10-15 ನಿಮಿಷಗಳ ಕಾಲ ನಡೆಯುವುದು ರಕ್ತದಲ್ಲಿನ ಗ್ಲೂಕೋಸ್ ಅನ್ನು ತೆರವುಗೊಳಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಬಿಳಿ ಅನ್ನದ ಬದಲಿಗೆ ಸಿರಿಧಾನ್ಯಗಳನ್ನು ಬಳಸಲು ಪ್ರಯತ್ನಿಸಿ.",
  "insight.stayingHydrated": "ಸಾಕಷ್ಟು ನೀರು ಕುಡಿಯುವುದು ಮುಖ್ಯ! ಊಟಕ್ಕೆ ಮುಂಚೆ ನೀರು ಕುಡಿಯುವುದು ಗ್ಲೂಕೋಸ್ ಏರಿಕೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಮತ್ತು ಚಯಾಪಚಯವನ್ನು ಬೆಂಬಲಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
  "insight.pairCarbsWithProtein": "ಕಾರ್ಬೋಹೈಡ್ರೇಟ್‌ಗಳೊಂದಿಗೆ ಆರೋಗ್ಯಕರ ಕೊಬ್ಬುಗಳು ಅಥವಾ ಪ್ರೋಟೀನ್‌ಗಳನ್ನು (ಬೀಜಗಳು, ಆವಕಾಡೊ ಅಥವಾ ಮೊಟ್ಟೆಗಳಂತಹವು) ಸೇವಿಸುವುದರಿಂದ ಜೀರ್ಣಕ್ರಿಯೆ ನಿಧಾನವಾಗಿ ಗ್ಲೂಕೋಸ್ ಏರಿಕೆಯನ್ನು ತಡೆಯುತ್ತದೆ.",
  "insight.qualitySleepInsulin": "ರಾತ್ರಿ 7-8 ಗಂಟೆಗಳ ಉತ್ತಮ ನಿದ್ರೆಯು ಇನ್ಸುಲಿನ್ ಸೂಕ್ಷ್ಮತೆಯನ್ನು ಸುಧಾರಿಸುತ್ತದೆ ಮತ್ತು ಉಪವಾಸದ ಗ್ಲೂಕೋಸ್ ಮಟ್ಟವನ್ನು ಸ್ಥಿರಗೊಳಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
  "insight.stressCortisolGlucose": "ಹೆಚ್ಚಿನ ಒತ್ತಡವು ಕಾರ್ಟಿಸೋಲ್ ಅನ್ನು ಬಿಡುಗಡೆ ಮಾಡುತ್ತದೆ, ಇದು ಆಹಾರವಿಲ್ಲದಿದ್ದರೂ ಗ್ಲೂಕೋಸ್ ಮಟ್ಟವನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ. ಒತ್ತಡವಿದ್ದಾಗ 5 ನಿಮಿಷ ಆಳವಾದ ಉಸಿರಾಟವನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿ.",
  "insight.eatMealsInOrder": "ಊಟವನ್ನು ಈ ಕ್ರಮದಲ್ಲಿ ಸೇವಿಸಲು ಪ್ರಯತ್ನಿಸಿ: ಮೊದಲು ತರಕಾರಿಗಳು, ನಂತರ ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬುಗಳು, ಕೊನೆಯಲ್ಲಿ ಕಾರ್ಬೋಹೈಡ್ರೇಟ್‌ಗಳು. ಇದು ಗ್ಲೂಕೋಸ್ ಸ್ಪೈಕ್ ಅನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.",
