  "cancerDesc.Colorectum": "ಆಧುನಿಕ ಜೀವನಶೈಲಿ, ಅಲ್ಟ್ರಾ-ಸಂಸ್ಕರಿಸಿದ ಆಹಾರಗಳು ಮತ್ತು ದೈಹಿಕ ಚಟುವಟಿಕೆಯ ಕೊರತೆಯಿಂದಾಗಿ ದೊಡ್ಡ ಕರುಳಿನ ಕ್ಯಾನ್ಸರ್‌ಗಳು ವೇಗವಾಗಿ ಹೆಚ್ಚುತ್ತಿವೆ.",
  "cancerDesc.Stomach": "ಹೆಚ್ಚಿನ ಉಪ್ಪಿನ ಸೇವನೆ ಮತ್ತು ಎಚ್. ಪೈಲೋರಿ ಬ್ಯಾಕ್ಟೀರಿಯಾದಂತಹ ಆಹಾರ ಪದ್ಧತಿಗಳೊಂದಿಗೆ ಹೊಟ್ಟೆಯ ಕ್ಯಾನ್ಸರ್ ಸಂಬಂಧ ಹೊಂದಿದೆ.",
  "cancerDesc.Prostate": "ವಯಸ್ಸಾದಂತೆ ಪ್ರಾಸ್ಟೇಟ್ ಕ್ಯಾನ್ಸರ್ ಹೆಚ್ಚಾಗುತ್ತದೆ ಮತ್ತು ಹೆಚ್ಚಿನ ಅಪಾಯವಿರುವವರಿಗೆ ತಪಾಸಣೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.",
  "cancerDesc.Other cancers": "ಇತರ ವಿವಿಧ ಕ್ಯಾನ್ಸರ್‌ಗಳ ಸಾಮೂಹಿಕ ಪಾಲು, ಪ್ರತಿಯೊಂದೂ ಒಟ್ಟು ಸಂಖ್ಯೆಯಲ್ಲಿ ಸಣ್ಣ ಪಾಲನ್ನು ಹೊಂದಿದೆ.",
  "cancerDesc.Breast": "ಭಾರತೀಯ ಮಹಿಳೆಯರಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅತ್ಯಂತ ಸಾಮಾನ್ಯವಾಗಿದ್ದು, ನಗರ ಪ್ರದೇಶಗಳಲ್ಲಿ ಇದರ ಪ್ರಮಾಣ ಹೆಚ್ಚುತ್ತಿದೆ.",
  "cancerDesc.Cervix uteri": "ಸಮಯೋಚಿತ ಎಚ್‌ಪಿವಿ ಲಸಿಕೆ ಮತ್ತು ನಿಯಮಿತ ತಪಾಸಣೆಯ (ಪ್ಯಾಪ್ ಸ್ಮಿಯರ್) ಮೂಲಕ ಗರ್ಭಕಂಠದ ಕ್ಯಾನ್ಸರ್ ಅನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ತಡೆಗಟ್ಟಬಹುದು.",
